ALTER SESSION SET CONTAINER=FREEPDB1;
CREATE USER aceu IDENTIFIED BY "aceu_local_only" DEFAULT TABLESPACE users QUOTA UNLIMITED ON users;
GRANT CREATE SESSION, CREATE TABLE, CREATE PROCEDURE, CREATE SEQUENCE, CREATE TYPE TO aceu;
CREATE USER aceu_app IDENTIFIED BY "aceu_app_local_only";
GRANT CREATE SESSION TO aceu_app;
GRANT INHERIT PRIVILEGES ON USER aceu_app TO aceu;
ALTER SESSION SET CURRENT_SCHEMA=aceu;
CREATE TABLE profiles(profile_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, display_name VARCHAR2(100) NOT NULL, context_name VARCHAR2(80) NOT NULL, payload CLOB CHECK(payload IS JSON), skills_vector VECTOR(10,FLOAT32), created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE artifacts(artifact_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id NUMBER NOT NULL REFERENCES profiles,artifact_type VARCHAR2(40) NOT NULL,skills_json CLOB CHECK(skills_json IS JSON),embedding VECTOR(10,FLOAT32),authored_at TIMESTAMP);
CREATE TABLE interactions(interaction_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id NUMBER NOT NULL REFERENCES profiles,interaction_type VARCHAR2(40) NOT NULL,quality NUMBER(8,6),reciprocity NUMBER(8,6));
CREATE TABLE scores(score_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id NUMBER NOT NULL REFERENCES profiles,context_name VARCHAR2(80) NOT NULL,a_score NUMBER(8,6),c_score NUMBER(8,6),e_score NUMBER(8,6),u_score NUMBER(8,6),a_uncertainty NUMBER(8,6),c_uncertainty NUMBER(8,6),e_uncertainty NUMBER(8,6),u_uncertainty NUMBER(8,6),explanation VARCHAR2(2000),computed_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE consent(profile_id NUMBER PRIMARY KEY REFERENCES profiles,consented CHAR(1) CHECK(consented IN('Y','N')),scope VARCHAR2(100),updated_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL);
CREATE TABLE contest_log(contest_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id NUMBER NOT NULL REFERENCES profiles,score_id NUMBER REFERENCES scores,action VARCHAR2(20) CHECK(action IN('contest','correct','override')),reason VARCHAR2(2000) NOT NULL,proposed_value NUMBER(8,6),status VARCHAR2(20) DEFAULT 'open' NOT NULL,created_at TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,resolved_at TIMESTAMP);
